import React from 'react';
import Chatbot from './components/Chatbot';
import './styles.css';

function App() {
  return (
    <div className="App">
      <h1>Mental Health Companion</h1>
      <p style={{color: '#555', fontSize: '0.95rem'}}>
        I'm an AI support chat — not a replacement for professional help.<br/>
        If you're in crisis, please call a helpline immediately.
      </p>
      <Chatbot />
    </div>
  );
}

export default App;
